cssCode:
.glitch-wrap {
  font-size: 50px; font-weight: 900; color: #fff;
  font-family: monospace; letter-spacing: 5px; position: relative;
  cursor: pointer; text-transform: uppercase;
}
.glitch-wrap::before, .glitch-wrap::after {
  content: attr(data-text); position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  background: #111; display: flex; align-items: center; justify-content: center;
  transition: opacity 0.3s; opacity: 0;
}
.glitch-wrap:hover::before, .glitch-wrap:active::before {
  opacity: 1; left: 3px; text-shadow: -2px 0 #ff007f;
  clip-path: polygon(0 10%, 100% 10%, 100% 30%, 0 30%);
  animation: glitch-anim 0.2s infinite linear alternate-reverse;
}
.glitch-wrap:hover::after, .glitch-wrap:active::after {
  opacity: 1; left: -3px; text-shadow: -2px 0 #00ffcc;
  clip-path: polygon(0 70%, 100% 70%, 100% 90%, 0 90%);
  animation: glitch-anim 0.3s infinite linear alternate-reverse;
}
@keyframes glitch-anim { 0% { transform: translate(0); } 100% { transform: translate(-4px, 2px); } }

